INSERT INTO survey_templates (id, code, title, target_respondent, questions_json, is_active) VALUES (1, 'SURVEY_ORTU', 'Kuesioner Kepuasan Layanan Sekolah (Orang Tua)', 'Orang Tua', '{"A": {"title": "A. Layanan Pembayaran", "items": ["Respon komunikasi petugas dalam melayani pembayaran", "Kecepatan layanan pembayaran di tempat", "Frekuensi pengingat kewajiban pembayaran", "Kemudahan proses pembayaran via transfer", "Kejelasan informasi biaya dan tagihan sekolah", "Pilihan metode pembayaran yang tersedia", "Kelengkapan dan ketepatan bukti pembayaran"]}, "B": {"title": "B. Layanan Kesehatan (UKS)", "items": ["Ketepatan penanganan pertama saat siswa sakit", "Komunikasi kepada orangtua terkait tindak lanjut kesehatan", "Keramahan petugas kesehatan"]}, "C": {"title": "C. Fasilitas", "items": ["Ketersediaan & kondisi ruang kelas", "Ketersediaan & kondisi lapangan / tempat bermain", "Ketersediaan & kondisi tempat ibadah / masjid", "Ketersediaan & kondisi tempat makan siswa", "Ketersediaan & kondisi tempat jajan santri / mini market", "Ketersediaan & kondisi suplai air bersih"]}, "D1": {"title": "D.1 Komunikasi Wali Kelas dan Guru dengan Orangtua", "items": ["Responsif dalam komunikasi", "Bahasa yang digunakan jelas & santun", "Frekuensi & kejelasan informasi terkait siswa/kegiatan sekolah"]}, "D2": {"title": "D.2 Layanan Pembelajaran oleh Guru", "items": ["Metode pengajaran dalam kelas", "Metode evaluasi & penilaian", "Kehadiran & kedisiplinan guru", "Keteladanan guru dalam berakhlak karimah", "Perhatian guru terhadap siswa", "Media pembelajaran yang digunakan", "Pembiasaan penggunaan bahasa asing"]}, "D3": {"title": "D.3 Ketercapaian Pembelajaran Siswa", "items": ["Ketercapaian pembelajaran Tahfidzul Qur''an", "Ketercapaian pembelajaran Bahasa Arab", "Ketercapaian pembelajaran Ilmu Agama", "Ketercapaian pembelajaran Ilmu Umum & Teknologi", "Anak memahami materi Pelajaran sesuai jenjangnya", "Anak mampu memanfaatkan teknologi secara tepat dan bertanggung jawab", "Anak menunjukkan kreativitas dalam belajar", "Anak mampu bekerja sama dengan teman (kolaborasi)", "Anak mampu mengelola waktu dan menyelesaikan tugas dengan baik (produktivitas)", "Anak mampu berkomunikasi dengan sopan dan efektif"]}, "D4": {"title": "D.4 Ketercapaian Perubahan Sikap, Akhlak, dan Ibadah Siswa", "items": ["Ibadah siswa sesuai tuntunan (Anak menunjukkan perilaku religious dan akhlak yang baik)", "Sikap siswa terhadap orangtua & keluarga", "Sikap siswa terhadap orang lain", "Akhlak & adab siswa dalam kegiatan sehari-hari", "Anak bersikap disiplin dalam belajar dan aktivitas harian", "Anak bertanggung jawab terhadap tugas dan kewajibannya", "Anak bersikap jujur dalam perkataan dan perbuatan"]}, "D5": {"title": "D.5 Sarana & Prasarana Pembelajaran", "items": ["Media pembelajaran / alat peraga di kelas", "Laboratorium IPA (Biologi, Fisika, Kimia)", "Laboratorium Komputer", "Perpustakaan / pojok literasi"]}, "E": {"title": "E. Kepuasan Secara Umum", "items": ["Sikap staf & guru dalam membantu dan melayani", "Keramahan staf & guru", "Kejelasan alur penyampaian keluhan atau saran", "Respons sekolah terhadap keluhan", "Kebersihan lingkungan sekolah", "Keamanan lingkungan sekolah"]}}', 1) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO survey_templates (id, code, title, target_respondent, questions_json, is_active) VALUES (2, 'SURVEY_KEPSEK', 'Kuesioner Kepuasan Guru & Staf terhadap Kepala Sekolah', 'Guru', '{"A": {"title": "Kepemimpinan & Keteladanan", "items": ["Kepala sekolah memberikan arahan program kerja dengan jelas dan terarah", "Kepala sekolah menjadi teladan dalam kedisiplinan dan ibadah", "Kepala sekolah terbuka terhadap masukan dan kritik konstruktif"]}, "B": {"title": "Manajemen & Dukungan Pembelajaran", "items": ["Kepala sekolah memberikan dukungan fasilitas untuk proses KBM dan tahfidz", "Kepala sekolah mengapresiasi pencapaian dan kinerja guru", "Kepala sekolah adil dan bijaksana dalam penyelesaian permasalahan guru/staf"]}}', 1) ON DUPLICATE KEY UPDATE title=VALUES(title);
INSERT INTO survey_templates (id, code, title, target_respondent, questions_json, is_active) VALUES (3, 'SURVEY_SISWA', 'Kuesioner Kepuasan Siswa terhadap Layanan Sekolah (SMP/SMA)', 'Siswa', '{"A": {"title": "Kepuasan Layanan Pembelajaran di Sekolah", "items": ["Guru mengajar dengan jelas, menarik, dan mudah dipahami", "Fasilitas kelas dan laboratorium mendukung pembelajaran dengan baik", "Program tahfidz dan kegiatan keagamaan membimbing ibadah saya", "Sekolah memberikan kesempatan menyalurkan minat, bakat, dan lomba", "Lingkungan sekolah aman, nyaman, dan bersih untuk belajar"]}}', 1) ON DUPLICATE KEY UPDATE title=VALUES(title);
